SELECT SUM(value) AS mrr_q2
FROM (
  SELECT 392.45499999999987 AS value
  UNION ALL SELECT 510.3041666666666
  UNION ALL SELECT 750.8849999999999
) t;

WITH prev AS (
  SELECT SUM(value) AS prev_week_users
  FROM (VALUES
    (DATE '2026-06-29',319),(DATE '2026-06-30',317),(DATE '2026-07-01',321),(DATE '2026-07-02',308),(DATE '2026-07-03',341),(DATE '2026-07-04',319),(DATE '2026-07-05',347)
  ) AS t(day, value)
), last AS (
  SELECT SUM(value) AS last_week_users
  FROM (VALUES
    (DATE '2026-07-06',278),(DATE '2026-07-07',331),(DATE '2026-07-08',294),(DATE '2026-07-09',268),(DATE '2026-07-10',287),(DATE '2026-07-11',273),(DATE '2026-07-12',281)
  ) AS t(day, value)
)
SELECT prev_week_users, last_week_users, (last_week_users - prev_week_users) AS diff FROM prev, last;

SELECT SUM(fte) AS employees
FROM fct_employees
WHERE date >= '2026-04-01' AND date <= '2026-06-30';

SELECT SUM(value_moments) AS total_habits, SUM(app_opens) AS total_sessions_approx
FROM fct_user_days
WHERE active_date BETWEEN '2025-09-01' AND '2026-07-12' ;
